JUDGE_TEMPLATE = """You are grading an answer to a question.
Question: {question}
Answer: {answer}

Score the answer from 1 to 5 using this rubric:
5 = fully correct, complete and concise
3 = partially correct or missing key details
1 = incorrect or off-topic

Reply with JSON only: {{"score": <int>, "reason": "<one sentence>"}}"""


def judge_prompt(question: str, answer: str) -> str:
    return JUDGE_TEMPLATE.format(question=question, answer=answer)


def pairwise_verdict(ask_judge, prompt, a, b):
    # Run both orders; keep the verdict only when they agree.
    first = ask_judge(prompt, a, b)    # returns "A" or "B"
    second = ask_judge(prompt, b, a)   # swapped order
    if first == "A" and second == "B":
        return "a"
    if first == "B" and second == "A":
        return "b"
    return "tie_or_position_bias"

def reciprocal_rank_fusion(rankings, k=60):
    """rankings: list of ranked doc-id lists, e.g. [bm25_ids, embedding_ids]."""
    scores = {}
    for ranked in rankings:
        for rank, doc_id in enumerate(ranked, start=1):
            scores[doc_id] = scores.get(doc_id, 0.0) + 1.0 / (k + rank)
    return sorted(scores.items(), key=lambda kv: kv[1], reverse=True)


bm25_hits = ["d3", "d1", "d7", "d2"]      # exact-term matches
embed_hits = ["d1", "d9", "d3", "d4"]     # semantic matches

for doc_id, score in reciprocal_rank_fusion([bm25_hits, embed_hits])[:3]:
    print(doc_id, round(score, 4))
# d1 and d3 rise to the top because both retrievers agree on them.
